    {"id": 96, "title": "L'objet-personnage", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 3, "consigne": "Raconte une histoire où un objet ordinaire devient progressivement le véritable protagoniste du récit."},
    {"id": 97, "title": "La contrainte du temps réel", "type": "Écriture avec contrainte", "genre": "policier/thriller", "difficulty": 3, "consigne": "Écris une scène de désamorçage ou de course contre la montre où le temps du récit correspond exactement au temps réel de l'action."},
    {"id": 98, "title": "Portrait par juxtaposition", "type": "Portrait", "genre": "comédie", "difficulty": 3, "consigne": "Fais le portrait de deux personnages opposés en alternant une phrase sur l'un, une phrase sur l'autre, sans transition."},
    {"id": 99, "title": "L'incipit à la deuxième personne", "type": "Incipit", "genre": "drame intimiste", "difficulty": 3, "consigne": "Écris un incipit à la deuxième personne du singulier (« tu »), qui plonge directement le lecteur dans l'action."},
    {"id": 100, "title": "La chute en écho", "type": "Chute de nouvelle", "genre": "fantastique", "difficulty": 3, "consigne": "Écris la chute d'une nouvelle qui reprend mot pour mot la première phrase du texte, mais avec un sens complètement inversé."},
    {"id": 101, "title": "Le carnet de bord halluciné", "type": "Écriture libre", "genre": "aventure", "difficulty": 3, "consigne": "Raconte, sous forme de carnet de bord, la dérive progressive vers la folie d'un explorateur isolé."},
    {"id": 102, "title": "Le dialogue interrompu", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 3, "consigne": "Écris un interrogatoire où chaque réplique du suspect est coupée avant la fin par une réplique de l'enquêteur."},
    {"id": 103, "title": "La réécriture par les sens", "type": "Réécriture", "genre": "horreur", "difficulty": 3, "consigne": "Réécris une scène de suspense en changeant le sens dominant utilisé pour créer la peur (du visuel vers le sonore ou l'olfactif)."},
    {"id": 104, "title": "Le monde à l'envers", "type": "Écriture avec contrainte", "genre": "science-fiction", "difficulty": 3, "consigne": "Imagine une société où une valeur morale actuelle est totalement inversée, et montre-le uniquement à travers une scène de vie quotidienne."},
    {"id": 105, "title": "Portrait à travers un tic", "type": "Portrait", "genre": "comédie", "difficulty": 3, "consigne": "Fais le portrait d'un personnage à travers un seul tic de langage ou geste répété, sans jamais le décrire physiquement autrement."},
    {"id": 106, "title": "La lettre non censurée", "type": "Écriture libre", "genre": "historique", "difficulty": 3, "consigne": "Écris la lettre qu'un personnage historique méconnu aurait pu écrire juste avant un événement célèbre."},
    {"id": 107, "title": "Le huis clos sensoriel", "type": "Description", "genre": "huis clos", "difficulty": 3, "consigne": "Décris un lieu clos (cave, sous-marin, refuge) uniquement à travers ce que perçoivent les personnages dans le noir."},
    {"id": 108, "title": "La réécriture par omission", "type": "Réécriture", "genre": "drame intimiste", "difficulty": 3, "consigne": "Réécris une scène en supprimant toute description explicite d'émotion : celle-ci doit se deviner uniquement par les actions."},
    {"id": 109, "title": "Le dialogue en une langue étrangère mêlée", "type": "Dialogue", "genre": "réalisme contemporain", "difficulty": 3, "consigne": "Écris un dialogue entre deux personnages qui ne parlent pas la même langue, en jouant sur les malentendus et les gestes."},
    {"id": 110, "title": "La chute annoncée", "type": "Chute de nouvelle", "genre": "drame intimiste", "difficulty": 3, "consigne": "Écris une nouvelle courte dont la chute est annoncée dès la première phrase, sans que cela n'enlève sa force."},
    {"id": 111, "title": "Portrait par le regard des autres", "type": "Portrait", "genre": "comédie", "difficulty": 3, "consigne": "Fais le portrait d'un personnage à travers trois avis contradictoires que d'autres personnages ont de lui."},
    {"id": 112, "title": "L'incipit sonore", "type": "Incipit", "genre": "horreur", "difficulty": 3, "consigne": "Écris un incipit construit uniquement autour d'un bruit inquiétant, entendu avant qu'on en comprenne l'origine."},
    {"id": 113, "title": "La contrainte du dialogue seul", "type": "Écriture avec contrainte", "genre": "comédie", "difficulty": 3, "consigne": "Raconte une scène entière uniquement en dialogue, sans aucune didascalie ni description."},
    {"id": 114, "title": "Le voyage immobile", "type": "Écriture libre", "genre": "conte merveilleux", "difficulty": 3, "consigne": "Raconte un grand voyage initiatique qui se déroule en réalité entièrement dans l'esprit d'un personnage immobile."},
    {"id": 115, "title": "La réécriture par changement d'époque", "type": "Réécriture", "genre": "historique", "difficulty": 3, "consigne": "Réécris une scène de conflit contemporain (dispute familiale, rupture) comme si elle se déroulait à la cour de Louis XIV."},
    {"id": 116, "title": "Portrait à la loupe", "type": "Portrait", "genre": "drame intimiste", "difficulty": 3, "consigne": "Fais le portrait d'un personnage en te concentrant exclusivement sur un seul détail physique pendant tout le texte."},
    {"id": 117, "title": "Le dialogue de la trahison", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 3, "consigne": "Écris une scène où un personnage découvre en direct, à travers les mots de l'autre, qu'il est trahi."},
    {"id": 118, "title": "La description impossible", "type": "Description", "genre": "fantastique", "difficulty": 3, "consigne": "Décris une créature ou un lieu que le narrateur admet lui-même ne pas réussir à décrire complètement."},
    {"id": 119, "title": "L'incipit qui ment", "type": "Incipit", "genre": "policier/thriller", "difficulty": 3, "consigne": "Écris un incipit qui donne une fausse impression de genre au lecteur, avant un basculement prévu plus tard."},
    {"id": 120, "title": "La chute en une image", "type": "Chute de nouvelle", "genre": "poésie en prose", "difficulty": 3, "consigne": "Écris la chute d'une nouvelle en une seule image poétique, sans explication ni commentaire."},

    # ==========================================
    # DIFFICULTÉ 4 — Avancé
    # ==========================================
    {"id": 121, "title": "Le narrateur non fiable total", "type": "Écriture avec contrainte", "genre": "policier/thriller", "difficulty": 4, "consigne": "Raconte un meurtre à la première personne où le narrateur, sans jamais mentir explicitement, dissimule sa propre culpabilité par la structure même du récit."},
    {"id": 122, "title": "Trois points de vue, une vérité fragmentée", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 4, "consigne": "Raconte un même accident familial à travers trois points de vue successifs qui se contredisent partiellement, sans jamais trancher qui a raison."},
    {"id": 123, "title": "Le monologue schizophrène", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 4, "consigne": "Écris un monologue intérieur où deux voix contradictoires du même personnage s'affrontent sans marqueur typographique pour les distinguer clairement."},
    {"id": 124, "title": "La dystopie par la novlangue", "type": "Écriture avec contrainte", "genre": "dystopie", "difficulty": 4, "consigne": "Invente un vocabulaire propre à une société totalitaire et raconte une scène de vie quotidienne en l'utilisant naturellement, sans glossaire ni explication."},
    {"id": 125, "title": "Le lipogramme narratif complet", "type": "Écriture avec contrainte", "genre": "réalisme contemporain", "difficulty": 4, "consigne": "Écris une scène complète (au moins 200 mots) racontant une rupture amoureuse sans jamais utiliser la lettre « a »."},
    {"id": 126, "title": "La réécriture en abyme", "type": "Réécriture", "genre": "fantastique", "difficulty": 4, "consigne": "Réécris une scène en y intégrant un personnage qui est en train d'écrire cette même scène, sans que le procédé ne soit jamais explicité."},
    {"id": 127, "title": "L'horreur par la banalité", "type": "Écriture avec contrainte", "genre": "horreur", "difficulty": 4, "consigne": "Raconte une scène terrifiante en conservant du début à la fin un ton parfaitement neutre et administratif, sans aucun mot connoté."},
    {"id": 128, "title": "Le huis clos à mémoire trouée", "type": "Écriture libre", "genre": "huis clos", "difficulty": 4, "consigne": "Fais vivre un huis clos entre plusieurs personnages dont l'un a une amnésie partielle, et laisse le lecteur reconstituer ce qu'il a oublié."},
    {"id": 129, "title": "La structure en miroir", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 4, "consigne": "Écris une scène où la deuxième moitié du texte reprend exactement la structure de phrases de la première moitié, mais avec un sens opposé."},
    {"id": 130, "title": "Le dialogue à sens unique révélé", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 4, "consigne": "Écris un dialogue téléphonique où le lecteur ne perçoit qu'un seul interlocuteur, et doit deviner l'intégralité de ce que dit l'autre."},
    {"id": 131, "title": "La poésie en prose contrainte métrique", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 4, "consigne": "Écris un texte en prose poétique où chaque phrase compte exactement le même nombre de syllabes."},
    {"id": 132, "title": "Le récit à double lecture", "type": "Écriture avec contrainte", "genre": "romance", "difficulty": 4, "consigne": "Écris un texte qui peut se lire de deux façons opposées (comme une rencontre heureuse ou un adieu déchirant) selon l'interprétation du lecteur."},
    {"id": 133, "title": "La réécriture en réduction extrême", "type": "Réécriture", "genre": "drame intimiste", "difficulty": 4, "consigne": "Réécris une scène de deux pages en exactement six phrases, sans perdre l'essentiel de la tension dramatique."},
    {"id": 134, "title": "Le conte merveilleux politique", "type": "Écriture libre", "genre": "conte merveilleux", "difficulty": 4, "consigne": "Écris un conte merveilleux dont la morale critique implicitement un système de pouvoir actuel, sans jamais nommer ce système."},
    {"id": 135, "title": "Le portrait par la négative absolue", "type": "Portrait", "genre": "drame intimiste", "difficulty": 4, "consigne": "Fais le portrait complet d'un personnage sans jamais utiliser un seul adjectif, uniquement par ses actions et ses choix."},
    {"id": 136, "title": "La science-fiction du langage", "type": "Écriture avec contrainte", "genre": "science-fiction", "difficulty": 4, "consigne": "Imagine une civilisation dont la perception du temps est différente de la nôtre, et fais-le ressentir uniquement par la construction grammaticale des phrases."},
    {"id": 137, "title": "L'incipit qui ne commence pas", "type": "Incipit", "genre": "fantastique", "difficulty": 4, "consigne": "Écris un incipit qui donne l'impression que l'histoire a déjà commencé bien avant, sans jamais combler ce manque d'information."},
    {"id": 138, "title": "La chute qui rouvre l'histoire", "type": "Chute de nouvelle", "genre": "policier/thriller", "difficulty": 4, "consigne": "Écris une chute qui, en une phrase, oblige le lecteur à reconsidérer entièrement le sens de tout ce qui précède."},
    {"id": 139, "title": "Le dialogue générationnel sur trois voix", "type": "Dialogue", "genre": "drame intimiste", "difficulty": 4, "consigne": "Écris une scène à trois générations (grand-parent, parent, enfant) où chacun parle un registre de langue radicalement différent, sans jamais l'expliquer."},
    {"id": 140, "title": "La réécriture en changement de genre littéraire", "type": "Réécriture", "genre": "horreur", "difficulty": 4, "consigne": "Réécris une scène de comédie romantique comme une scène d'horreur pure, en gardant exactement la même trame d'événements."},
    {"id": 141, "title": "L'aventure sans héros", "type": "Écriture libre", "genre": "aventure", "difficulty": 4, "consigne": "Raconte une grande aventure épique uniquement du point de vue de personnages secondaires qui ne comprennent qu'une partie de ce qui se joue."},
    {"id": 142, "title": "Le huis clos à plusieurs temporalités", "type": "Écriture avec contrainte", "genre": "huis clos", "difficulty": 4, "consigne": "Fais coexister dans un même lieu clos deux époques différentes, sans jamais utiliser de mécanisme de science-fiction explicite pour le justifier."},
    {"id": 143, "title": "La dystopie intime", "type": "Écriture libre", "genre": "dystopie", "difficulty": 4, "consigne": "Raconte une scène de tendresse familiale au cœur d'une dystopie oppressive, sans jamais que la tendresse ne devienne un acte de résistance explicite."},
    {"id": 144, "title": "Le portrait par accumulation contradictoire", "type": "Portrait", "genre": "comédie", "difficulty": 4, "consigne": "Fais le portrait d'un personnage en accumulant des détails de plus en plus contradictoires jusqu'à rendre le lecteur incapable de le juger clairement."},
    {"id": 145, "title": "La description qui ment sciemment", "type": "Description", "genre": "policier/thriller", "difficulty": 4, "consigne": "Décris une scène de crime de façon à orienter délibérément le lecteur vers un suspect innocent, sans jamais mentir factuellement."},
    {"id": 146, "title": "La réécriture en changement de narrateur non humain", "type": "Réécriture", "genre": "fantastique", "difficulty": 4, "consigne": "Réécris une scène de guerre du point de vue d'un élément non humain (le vent, un mur, une horloge) qui perçoit tout mais ne peut rien changer."},
    {"id": 147, "title": "Le récit à structure circulaire", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 4, "consigne": "Écris un texte dont la dernière phrase ramène exactement à la situation de la première, en ayant fait le tour complet d'une vie ou d'une journée."},
    {"id": 148, "title": "Le dialogue codé", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 4, "consigne": "Écris un dialogue en apparence anodin entre deux espions, où chaque réplique cache un message codé compréhensible seulement en relisant le texte."},
    {"id": 149, "title": "La poésie en prose du corps vieillissant", "type": "Écriture libre", "genre": "poésie en prose", "difficulty": 4, "consigne": "Écris un texte en prose poétique sur le vieillissement du corps, sans une once de misérabilisme ni de pathos appuyé."},
    {"id": 150, "title": "L'incipit à voix multiples immédiates", "type": "Incipit", "genre": "drame intimiste", "difficulty": 4, "consigne": "Écris un incipit qui fait entendre, sans transition ni ponctuation classique, trois voix intérieures simultanées d'un même événement."},

    # ==========================================
    # DIFFICULTÉ 5 — Expert
    # ==========================================
    {"id": 151, "title": "Le récit sans aucun verbe conjugué", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Écris un texte narratif complet (au moins 150 mots) sans utiliser un seul verbe conjugué, uniquement des infinitifs, participes et noms."},
    {"id": 152, "title": "Le palindrome narratif", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 5, "consigne": "Écris une histoire courte dont la seconde moitié reprend exactement les mêmes phrases que la première, mais dans l'ordre inverse, avec un sens totalement nouveau."},
    {"id": 153, "title": "Le récit à contraintes multiples cumulées", "type": "Écriture avec contrainte", "genre": "policier/thriller", "difficulty": 5, "consigne": "Écris une scène de crime en respectant simultanément trois contraintes : aucun dialogue direct, aucun adjectif, et un unique point de vue non fiable."},
    {"id": 154, "title": "La novlangue totale", "type": "Écriture avec contrainte", "genre": "dystopie", "difficulty": 5, "consigne": "Écris une scène entière dans une langue inventée cohérente (au moins vingt mots récurrents), rendue compréhensible uniquement par le contexte, sans aucun lexique fourni."},
    {"id": 155, "title": "Le monologue à quatre strates temporelles", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris un monologue intérieur qui mêle sans transition typographique quatre époques de la vie d'un même personnage, en un flux continu et cohérent."},
    {"id": 156, "title": "La chute qui précède le début", "type": "Écriture avec contrainte", "genre": "policier/thriller", "difficulty": 5, "consigne": "Écris une nouvelle complète où la chute (la révélation finale) est donnée dès la première ligne, et où tout le reste du texte doit pourtant maintenir un suspense réel."},
    {"id": 157, "title": "Le texte à lecture réversible", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Écris un texte dont les phrases, lues dans l'ordre inverse (de la dernière à la première), racontent une histoire différente mais tout aussi cohérente."},
    {"id": 158, "title": "L'horreur cosmique sans monstre", "type": "Écriture avec contrainte", "genre": "horreur", "difficulty": 5, "consigne": "Écris une scène d'horreur cosmique (au sens de Lovecraft) où l'angoisse vient uniquement de ce que le narrateur COMPREND, sans qu'aucune créature ne soit jamais décrite."},
    {"id": 159, "title": "Le récit à narrateur collectif", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris une scène entière narrée au « nous », incarnant la voix collective d'un groupe (un village, une classe), sans jamais individualiser un seul membre."},
    {"id": 160, "title": "La réécriture en contrainte oulipienne S+7", "type": "Réécriture", "genre": "comédie", "difficulty": 4, "consigne": "Réécris un court texte existant (que tu inventes d'abord) en appliquant la méthode S+7 : remplace chaque nom commun par le septième nom qui le suit dans un dictionnaire imaginaire cohérent."},
    {"id": 161, "title": "Le huis clos à cinq consciences fusionnées", "type": "Écriture avec contrainte", "genre": "science-fiction", "difficulty": 5, "consigne": "Écris une scène où cinq personnages partagent temporairement une même conscience télépathique, en rendant perceptible la confusion des « je » sans jamais perdre le lecteur."},
    {"id": 162, "title": "Le conte merveilleux à morale absente", "type": "Écriture libre", "genre": "conte merveilleux", "difficulty": 5, "consigne": "Écris un conte merveilleux qui respecte parfaitement la structure classique (formules, épreuves, résolution) mais qui refuse délibérément toute morale ou leçon finale."},
    {"id": 163, "title": "La structure fractale", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 5, "consigne": "Écris une histoire où une scène brève, racontée au début, se retrouve reproduite en miniature à trois niveaux différents du récit (un souvenir, un rêve, une prédiction)."},
    {"id": 164, "title": "Le récit à temporalité brisée totale", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Raconte une vie entière en fragments non chronologiques d'une phrase à trois phrases chacun, sans aucun marqueur temporel explicite, en laissant le lecteur reconstituer l'ordre."},
    {"id": 165, "title": "La dystopie par le silence total sur l'oppression", "type": "Écriture avec contrainte", "genre": "dystopie", "difficulty": 5, "consigne": "Décris une journée entière dans un régime totalitaire du point de vue d'un personnage qui ne perçoit AUCUNE oppression, en laissant le lecteur seul juge de l'horreur ambiante."},
    {"id": 166, "title": "Le texte à deux narrateurs entrelacés", "type": "Écriture avec contrainte", "genre": "romance", "difficulty": 4, "consigne": "Écris un texte où chaque phrase alterne strictement entre deux narrateurs différents, sans jamais l'indiquer typographiquement, uniquement par le style de chacun."},
    {"id": 167, "title": "Le lipogramme en deux voyelles", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Écris un texte poétique d'au moins cent mots en n'utilisant que les voyelles « a » et « i », en excluant totalement les autres."},
    {"id": 168, "title": "La chute qui invalide toute l'histoire", "type": "Chute de nouvelle", "genre": "fantastique", "difficulty": 5, "consigne": "Écris une nouvelle dont la chute révèle que le narrateur lui-même n'existe pas au sens propre (rêve, IA, personnage fictif dans la fiction), sans que cela ne semble être une facilité."},
    {"id": 169, "title": "Le récit en abîme à trois degrés", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 5, "consigne": "Écris un texte où un personnage lit un livre, dans lequel un personnage regarde un film, dans lequel un personnage raconte l'histoire que le lecteur est justement en train de lire."},
    {"id": 170, "title": "L'écriture automatique maîtrisée", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Écris un texte au fil de la plume façon surréaliste (associations libres, logique du rêve), tout en maintenant une cohérence émotionnelle perceptible de bout en bout."},
    {"id": 171, "title": "La comédie tragique simultanée", "type": "Écriture avec contrainte", "genre": "comédie", "difficulty": 5, "consigne": "Écris une scène strictement comique pour un personnage et strictement tragique pour un autre, dans le même dialogue, sans jamais rompre l'unité de la scène."},
    {"id": 172, "title": "Le portrait négatif absolu", "type": "Portrait", "genre": "drame intimiste", "difficulty": 5, "consigne": "Fais le portrait complet d'un personnage central sans jamais le nommer, le décrire physiquement, ni rapporter une seule de ses paroles directes."},
    {"id": 173, "title": "Le huis clos temporel infini", "type": "Écriture avec contrainte", "genre": "huis clos", "difficulty": 5, "consigne": "Raconte une boucle temporelle (le même événement qui recommence) où chaque répétition ne change qu'un détail minuscule, sur au moins trois itérations, sans jamais devenir répétitif pour le lecteur."},
    {"id": 174, "title": "La réécriture en contrainte lipogrammatique inversée", "type": "Réécriture", "genre": "réalisme contemporain", "difficulty": 4, "consigne": "Réécris une scène en n'utilisant QUE des mots contenant la lettre « x » ou « z » au moins une fois par phrase, de façon naturelle."},
    {"id": 175, "title": "Le texte au conditionnel intégral", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris une scène entière au conditionnel, comme une hypothèse jamais advenue, tout en la rendant aussi poignante qu'un fait réel."},
    {"id": 176, "title": "L'incipit à narrateur mourant", "type": "Incipit", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris l'incipit d'un récit narré par quelqu'un en train de mourir, où le style de la phrase se dégrade progressivement à mesure que la conscience du narrateur s'éteint."},
    {"id": 177, "title": "La science-fiction à logique non humaine", "type": "Écriture avec contrainte", "genre": "science-fiction", "difficulty": 5, "consigne": "Écris une scène du point de vue d'une intelligence artificielle dont la logique de pensée n'obéit à aucune des conventions narratives humaines habituelles, tout en restant lisible."},
    {"id": 178, "title": "Le dialogue à sens caché systématique", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 5, "consigne": "Écris un dialogue entier où chaque réplique a un double sens littéral et un sens caché, les deux devant rester cohérents d'un bout à l'autre de la scène."},
    {"id": 179, "title": "Le conte merveilleux au vocabulaire contemporain", "type": "Réécriture", "genre": "conte merveilleux", "difficulty": 4, "consigne": "Réécris un conte merveilleux traditionnel en conservant sa structure exacte mais en utilisant exclusivement un vocabulaire et des références du monde contemporain."},
    {"id": 180, "title": "La nouvelle à contrainte de longueur décroissante", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris une nouvelle où chaque paragraphe est exactement deux fois plus court que le précédent, jusqu'à se terminer par une phrase unique."},
    {"id": 181, "title": "Le récit à mémoire non fiable révélée par la syntaxe", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Raconte un souvenir d'enfance en faisant sentir, uniquement par des ruptures syntaxiques progressives, que la mémoire du narrateur se déforme au fil du texte."},
    {"id": 182, "title": "L'aventure à héros absent", "type": "Écriture avec contrainte", "genre": "aventure", "difficulty": 5, "consigne": "Raconte une grande quête épique sans jamais montrer le héros en scène : uniquement à travers les traces qu'il laisse et les récits des témoins."},
    {"id": 183, "title": "La poésie en prose à contrainte alphabétique", "type": "Écriture avec contrainte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Écris un texte poétique où chaque phrase successive commence par la lettre suivante de l'alphabet, de A à au moins M, sans que cela paraisse artificiel."},
    {"id": 184, "title": "Le texte à double généalogie temporelle", "type": "Écriture avec contrainte", "genre": "historique", "difficulty": 4, "consigne": "Raconte l'histoire d'une même famille sur quatre générations en une seule scène continue, où les personnages de chaque époque semblent se répondre les uns aux autres sans jamais se croiser littéralement."},
    {"id": 185, "title": "Le huis clos à un seul sens disponible", "type": "Description", "genre": "huis clos", "difficulty": 5, "consigne": "Décris un enlèvement ou une séquestration du point de vue d'un personnage aveugle, en construisant toute la tension uniquement par le son, le toucher et l'odorat."},
    {"id": 186, "title": "La réécriture en inversion complète des rôles", "type": "Réécriture", "genre": "policier/thriller", "difficulty": 5, "consigne": "Réécris une scène policière classique en inversant intégralement les rôles moraux (le criminel devient la victime du récit, le policier devient l'antagoniste), sans jamais le signaler explicitement au lecteur."},
    {"id": 187, "title": "Le texte à ellipse totale de l'événement central", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Raconte les conséquences d'un événement tragique majeur (accident, deuil, rupture) sans jamais le décrire directement, uniquement par ses ondes de choc successives."},
    {"id": 188, "title": "La comédie du non-dit tragique", "type": "Dialogue", "genre": "comédie", "difficulty": 4, "consigne": "Écris un dialogue comique entre deux personnages où l'un cache à l'autre une nouvelle tragique, en maintenant l'humour de surface jusqu'à la dernière réplique."},
    {"id": 189, "title": "Le récit en apesanteur temporelle", "type": "Écriture avec contrainte", "genre": "science-fiction", "difficulty": 5, "consigne": "Raconte une scène se déroulant dans un lieu où le temps ne s'écoule pas de façon linéaire, en rendant cette distorsion perceptible uniquement par la construction des phrases."},
    {"id": 190, "title": "Le monologue en accumulation d'négations", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris un monologue où le personnage ne définit jamais ce qu'il ressent positivement, uniquement par une accumulation de phrases négatives (« ce n'est pas », « je ne ressens pas »), jusqu'à une révélation implicite finale."},
    {"id": 191, "title": "Le texte au présent de narration total", "type": "Écriture avec contrainte", "genre": "aventure", "difficulty": 5, "consigne": "Écris un récit d'aventure haletant entièrement au présent de narration, sans un seul retour en arrière ni anticipation, comme si tout se produisait en temps réel devant le lecteur."},
    {"id": 192, "title": "La réécriture en contrainte de rimes internes", "type": "Réécriture", "genre": "poésie en prose", "difficulty": 4, "consigne": "Réécris un court passage narratif en y intégrant des rimes internes discrètes à l'intérieur des phrases, sans que le texte ne ressemble à un poème formel."},
    {"id": 193, "title": "Le conte à structure exactement symétrique", "type": "Écriture avec contrainte", "genre": "conte merveilleux", "difficulty": 4, "consigne": "Écris un conte dont la structure est parfaitement symétrique : chaque épreuve du début trouve un écho exact et inversé dans la seconde moitié du récit."},
    {"id": 194, "title": "Le texte halluciné à fiabilité déclinante", "type": "Écriture avec contrainte", "genre": "horreur", "difficulty": 5, "consigne": "Raconte la descente progressive dans la folie d'un personnage isolé, en faisant se dégrader la clarté même de la syntaxe et de la ponctuation au fil du texte, sans jamais devenir illisible."},
    {"id": 195, "title": "Le huis clos judiciaire à vérité multiple", "type": "Dialogue", "genre": "policier/thriller", "difficulty": 4, "consigne": "Écris une scène de procès où trois témoignages contradictoires sont chacun parfaitement crédibles et cohérents, sans qu'aucun indice ne permette de trancher lequel est vrai."},
    {"id": 196, "title": "Le texte à disparition progressive du narrateur", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 5, "consigne": "Raconte l'effacement progressif d'un personnage de la mémoire du monde qui l'entoure, en faisant disparaître peu à peu les traces de sa présence dans le texte lui-même (moins de dialogues qui lui sont adressés, moins de occurrences de son nom)."},
    {"id": 197, "title": "La romance à contrainte de non-rencontre", "type": "Écriture avec contrainte", "genre": "romance", "difficulty": 4, "consigne": "Raconte une histoire d'amour entre deux personnages qui ne se rencontrent jamais physiquement dans le texte, uniquement par lettres, objets ou témoins interposés."},
    {"id": 198, "title": "Le texte à contrainte de non-linéarité fractale totale", "type": "Écriture avec contrainte", "genre": "drame intimiste", "difficulty": 5, "consigne": "Raconte une vie entière en exactement neuf fragments non chronologiques, chacun faisant écho thématiquement (sans le dire) au fragment qui le précède immédiatement."},
    {"id": 199, "title": "La dystopie vue depuis l'intérieur du pouvoir", "type": "Écriture libre", "genre": "dystopie", "difficulty": 5, "consigne": "Raconte une journée de travail banale d'un rouage administratif d'un système oppressif, du point de vue de quelqu'un qui croit sincèrement bien faire, sans que le texte ne le juge jamais explicitement."},
    {"id": 200, "title": "Le texte somme, toutes contraintes réunies", "type": "Écriture avec contrainte", "genre": "fantastique", "difficulty": 5, "consigne": "Écris une nouvelle complète en choisissant et en cumulant volontairement au moins trois contraintes de cette banque d'exercices (lipogramme, structure en miroir, narrateur non fiable, etc.), en les citant en fin de texte."},

