    # ==========================================
    # Changement de point de vue (Focalisation)
    # ==========================================
    {"id": 1201, "title": "Le repas vu d'en bas", "type": "Changement de point de vue (Focalisation)", "genre": "réalisme contemporain", "difficulty": 1, "consigne": "Raconte un repas de famille du point de vue du plus jeune enfant, qui ne saisit que des bribes des tensions entre les adultes."},
    {"id": 1202, "title": "La trahison du vétérinaire", "type": "Changement de point de vue (Focalisation)", "genre": "comédie", "difficulty": 1, "consigne": "Raconte une visite chez le vétérinaire du point de vue du chien, intimement persuadé de vivre une trahison."},
    {"id": 1203, "title": "Le serveur témoin", "type": "Changement de point de vue (Focalisation)", "genre": "drame intimiste", "difficulty": 2, "consigne": "Raconte une rupture amoureuse depuis le point de vue du serveur du café qui observe la scène sans en connaître les enjeux."},
    {"id": 1204, "title": "La maison qui regarde l'orage", "type": "Changement de point de vue (Focalisation)", "genre": "fantastique", "difficulty": 2, "consigne": "Raconte l'arrivée d'un orage du point de vue de la maison elle-même, qui a vu passer des générations d'habitants."},
    {"id": 1205, "title": "Suivi sans le savoir", "type": "Changement de point de vue (Focalisation)", "genre": "policier/thriller", "difficulty": 3, "consigne": "Raconte une filature du point de vue de la personne suivie, qui ne comprend qu'à retardement, indice après indice, qu'on la piste."},
    {"id": 1206, "title": "Le domestique et le traité", "type": "Changement de point de vue (Focalisation)", "genre": "historique", "difficulty": 3, "consigne": "Raconte la signature d'un traité historique majeur du point de vue d'un domestique qui remplit les verres et ne saisit que l'écume des événements."},
    {"id": 1207, "title": "La sonde qui ne comprend pas", "type": "Changement de point de vue (Focalisation)", "genre": "science-fiction", "difficulty": 3, "consigne": "Raconte un premier contact extraterrestre du point de vue de la sonde robotisée qui l'enregistre sans en comprendre le sens."},
    {"id": 1208, "title": "Trois victimes, un dîner", "type": "Changement de point de vue (Focalisation)", "genre": "drame intimiste", "difficulty": 4, "consigne": "Raconte un même dîner de rupture successivement selon les trois convives, chacun étant intimement persuadé d'être la véritable victime."},
    {"id": 1209, "title": "La déclaration qu'on refuse", "type": "Changement de point de vue (Focalisation)", "genre": "romance", "difficulty": 4, "consigne": "Raconte une déclaration d'amour du point de vue de la personne qui la reçoit et n'en veut pas, sans jamais juger celui qui se déclare."},
    {"id": 1210, "title": "Le huis clos à focales tournantes", "type": "Changement de point de vue (Focalisation)", "genre": "huis clos", "difficulty": 5, "consigne": "Raconte un huis clos où le personnage focal change à chaque paragraphe, sans transition, chacun révélant une information que tous les autres ignorent."},

