    # ==========================================
    {"id": 1211, "title": "La ruelle sans issue", "type": "Scène de tension / d'action", "genre": "aventure", "difficulty": 1, "consigne": "Écris la fuite d'un personnage dans une ruelle, en n'utilisant que des phrases de moins de dix mots."},
    {"id": 1212, "title": "Le train qui part", "type": "Scène de tension / d'action", "genre": "réalisme contemporain", "difficulty": 1, "consigne": "Écris la scène où quelqu'un rate de justesse son train, en faisant sentir l'urgence uniquement par le rythme des phrases."},
    {"id": 1213, "title": "Poursuite au marché", "type": "Scène de tension / d'action", "genre": "policier/thriller", "difficulty": 2, "consigne": "Écris une course-poursuite à pied dans un marché bondé, sans jamais nommer explicitement l'émotion des personnages."},
    {"id": 1214, "title": "Les pas dans le noir", "type": "Scène de tension / d'action", "genre": "horreur", "difficulty": 2, "consigne": "Écris la scène où un personnage entend des pas se rapprocher dans l'obscurité, en dosant précisément l'accélération du rythme."},
    {"id": 1215, "title": "Compte à rebours", "type": "Scène de tension / d'action", "genre": "science-fiction", "difficulty": 3, "consigne": "Écris un désamorçage en temps réel où chaque phrase raccourcit à mesure que le compte à rebours avance."},
    {"id": 1216, "title": "La rivière en crue", "type": "Scène de tension / d'action", "genre": "aventure", "difficulty": 3, "consigne": "Écris une traversée de rivière en crue en alternant des phrases très courtes (l'action) et une unique phrase longue pour le moment suspendu."},
    {"id": 1217, "title": "Le duel immobile", "type": "Scène de tension / d'action", "genre": "fantasy", "difficulty": 4, "consigne": "Écris un duel à l'épée où toute la tension passe par les silences et les gestes minuscules, jamais par les coups eux-mêmes."},
    {"id": 1218, "title": "Évacuation sensorielle", "type": "Scène de tension / d'action", "genre": "huis clos", "difficulty": 4, "consigne": "Écris l'évacuation d'un immeuble en feu à travers les seules sensations physiques du personnage, sans aucun dialogue."},
    {"id": 1219, "title": "La prise d'otage immobile", "type": "Scène de tension / d'action", "genre": "policier/thriller", "difficulty": 5, "consigne": "Écris une prise d'otage où la tension monte alors qu'il ne se passe presque rien physiquement, uniquement par la construction des phrases."},
    {"id": 1220, "title": "Au bord de la violence", "type": "Scène de tension / d'action", "genre": "drame intimiste", "difficulty": 5, "consigne": "Écris une dispute qui menace à chaque instant de basculer dans la violence, où la tension repose entièrement sur ce qui n'est PAS dit."},

