    {"id": 1227, "title": "Logs de bord", "type": "Format épistolaire / Faux document", "genre": "science-fiction", "difficulty": 3, "consigne": "Raconte une mission spatiale qui tourne mal uniquement à travers les journaux de bord horodatés du vaisseau."},
    {"id": 1228, "title": "Lettres qui se manquent", "type": "Format épistolaire / Faux document", "genre": "drame intimiste", "difficulty": 4, "consigne": "Raconte une brouille familiale à travers un échange de lettres où chaque correspondant répond systématiquement à côté de ce que l'autre demande."},
    {"id": 1229, "title": "Les notes qui se dégradent", "type": "Format épistolaire / Faux document", "genre": "fantastique", "difficulty": 4, "consigne": "Écris une série de notes retrouvées dans une maison, dont l'écriture et la cohérence se dégradent à mesure qu'un phénomène s'installe."},
    {"id": 1230, "title": "Trois générations en documents", "type": "Format épistolaire / Faux document", "genre": "historique", "difficulty": 5, "consigne": "Raconte la chute d'une famille sur trois générations uniquement par des documents (acte de naissance, lettre, testament, faire-part)."},

