    {"id": 1233, "title": "Le basculement", "type": "Commentaire de texte", "genre": "fantastique", "difficulty": 3, "consigne": "Invente un passage fantastique, puis analyse comment l'auteur fait basculer le quotidien vers l'étrange en une phrase précise."},
    {"id": 1234, "title": "Le soupçon dès l'ouverture", "type": "Commentaire de texte", "genre": "policier/thriller", "difficulty": 3, "consigne": "Invente l'ouverture d'un polar, puis commente les procédés par lesquels l'auteur installe le soupçon dès les premières lignes."},
    {"id": 1235, "title": "Ancrer une époque", "type": "Commentaire de texte", "genre": "historique", "difficulty": 3, "consigne": "Invente un extrait situé au XIXe siècle, puis analyse comment le vocabulaire et le rythme ancrent le lecteur dans l'époque."},
    {"id": 1236, "title": "Le sous-texte au travail", "type": "Commentaire de texte", "genre": "drame intimiste", "difficulty": 4, "consigne": "Invente un dialogue chargé de sous-texte, puis commente comment le non-dit y produit plus de sens que les répliques elles-mêmes."},
    {"id": 1237, "title": "La peur du hors-champ", "type": "Commentaire de texte", "genre": "horreur", "difficulty": 4, "consigne": "Invente un passage d'horreur, puis analyse comment l'auteur crée la peur par ce qu'il choisit délibérément de NE PAS montrer."},
