    {"id": 1239, "title": "Un monde sans explication", "type": "Commentaire de texte", "genre": "science-fiction", "difficulty": 5, "consigne": "Invente un extrait de science-fiction, puis analyse comment l'auteur fait comprendre un monde entier sans jamais l'expliquer directement."},
    {"id": 1240, "title": "Commentaire composé", "type": "Commentaire de texte", "genre": "poésie en prose", "difficulty": 5, "consigne": "Invente un texte en prose poétique, puis rédige un commentaire composé qui dégage deux axes de lecture complémentaires."},
