# Normalisation : les entrées historiques utilisent des libellés courts ; on les
# ramène aux noms canoniques d'EXERCISE_TYPES (source unique de vérité).
for _ex in EXERCISES_BANK:
    _ex["type"] = _TYPE_ALIASES.get(_ex["type"], _ex["type"])

# Validation au chargement : aucun type ne doit sortir de la liste canonique.
_unknown_types = {e["type"] for e in EXERCISES_BANK} - set(EXERCISE_TYPE_NAMES)
if _unknown_types:
    raise ValueError(f"exercises_bank : types hors EXERCISE_TYPES : {sorted(_unknown_types)}")



def get_exercises_by_difficulty(level: int) -> list[dict]:
    return [e for e in EXERCISES_BANK if e["difficulty"] == level]


def get_exercises_by_genre(genre: str) -> list[dict]:
    g = genre.strip().lower()
    return [e for e in EXERCISES_BANK if g in e["genre"].lower() or e["genre"].lower() in g]


def get_exercises_by_type(exercise_type: str) -> list[dict]:
    t = exercise_type.strip().lower()
    return [e for e in EXERCISES_BANK if e["type"].lower() == t]


def get_random_exercise(difficulty: int | None = None) -> dict:
    import random

    pool = get_exercises_by_difficulty(difficulty) if difficulty else EXERCISES_BANK
    return random.choice(pool)
